def parse():
    out = []
    for ln in RAW.strip().split('\n'):
        sec, name, cl, eq, st, ac = ln.split('|')
        L = lambda x: [i.strip() for i in x.split(';')]
        out.append(dict(sec=sec, name=name, clothes=L(cl), equip=L(eq), setting=L(st), action=L(ac)))
    return out
